function task(t){t.configurationRows??=[];t.steps??=[];t.modifications??=[];t.accept??=[];t.inputs??=[];t.prerequisites??=[];t.refs??=[];t.assumptions??='None';t.reviewer??='Senior Consultant (product build manager; a different person from the implementer)';t.suppliedInputDescriptions=t.inputs.map(id=>({id,description:t.inputDescriptions[id]}));delete t.inputDescriptions;t.blockedStatus=t.inputs.length?'Partially blocked: '+t.suppliedInputDescriptions.map(i=>i.id+' — '+i.description).join(' '):'No missing supplied input for the listed configuration.';if(t.prerequisites.length)t.blockedStatus+=' Technical prerequisites: '+t.prerequisites.join(', ')+'.';tasks.push(t);return t;}
const coverage=[];
function addField(t,o,x){
 let def=x.contract[3];
 if(x.name==='Date'&&o===monthly)def='None; Refresh Establishment Monthly Metrics supplies the first day of the requested month';
 if(x.name==='Date'&&o===annual)def='None; Refresh Establishment Annual OSHA supplies January 1 of the requested year';
 if(x.name==='Year'&&o===annual)def='None; Refresh Establishment Annual OSHA stores the calendar year derived from Date; no continuing calculated expression is assigned';
 if(x.name==='OIISettings')def='No portable record GUID available; defer destination default binding to the supplied OII Setting input, never hard-code the source record GUID';
let behavior=o===master&&x.name==='Code'?'Administrator editable at creation and while unused; the later reference-dependent code guard is configured with the complete record-security outcome':x.contract[4];
 if(x.name==='OSHAEstablishment'&&[monthly,annual].includes(o))behavior='Read only on generated forms; supplied by '+(o===monthly?'Refresh Establishment Monthly Metrics':'Refresh Establishment Annual OSHA')+'; historical inactive references retained';
 const instruction=`Add ${x.caption} (${x.name}) on ${o.name} (${o.internalName}). Type/relationship: ${x.contract[1]}. Required: ${x.contract[2]}. Default/population setting: ${def}. Field/control behavior: ${behavior}.`;
 t.configurationRows.push([`${o.name}.${x.caption}`,instruction]);coverage.push({element:o.internalName+'.'+x.name,action:'Add',owner:t.id,source:x.sourceRecordId?`${ev(x.sourceGraphId)}; source GUID ${x.sourceRecordId}`:'Proposed revision 2',populationOwner:population(o,x)});
}
function population(o,x){if(x.contract[1].startsWith('Inverse'))return 'Native inverse navigation';if(o===hours&&['LocationHoursHeadcount','EstablishmentHoursHeadcount','SourceEntryID'].includes(x.name))return 'IMP-07';if([summ,loc].includes(o)&&['EmployeeHrs','ContractrHrs'].includes(x.name))return 'IMP-07';if(o===monthly)return 'IMP-08 (stored values); native/entry behavior for references and identity';if([annual,osha].includes(o))return 'IMP-09 (stored values); manual overrides retained';return 'Native default or authorized user entry';}
